/**
 * Generated by scaffold-fixtures-per-entity. Inserts a Questions row
 * directly via the repository. Useful for tests that need a pre-seeded record
 * without going through the full HTTP create flow.
 */
import { DataSource } from 'typeorm';

export interface CreateQuestionsInput {
  [key: string]: unknown;
}

export async function createTestQuestions(
  dataSource: DataSource,
  overrides: CreateQuestionsInput = {},
): Promise<Record<string, unknown>> {
  const meta = dataSource.entityMetadatas.find(
    (m) => m.name === 'Questions' || m.tableName === 'questions',
  );
  if (!meta) {
    throw new Error('createTestQuestions: Questions entity not registered with the DataSource');
  }
  const repo = dataSource.getRepository(meta.target);
  const row: Record<string, unknown> = {
    text: 'test-text',
    textBn: 'test-textBn',
    options: 'test-options',
    correctOption: 0,
    difficulty: 'test-difficulty',
    ...overrides,
  };
  const saved = await repo.save(row as never);
  return saved as unknown as Record<string, unknown>;
}
